3	// WHY. The site's footer names the released version in a `title` tooltip, so a
4	// visitor can say which build they are looking at. That number is a copy of
5	// `package.json`'s version — the single source of truth the release bumps — and
6	// a copy that drifts is worse than no number at all: it names a build that is
7	// not the one being served, and nothing about the page looks wrong.
8	//
9	// The copy is generated, not hand-maintained: `scripts/bump-version.mjs` writes
10	// the version into `package.json` and stamps it into every page carrying the
11	// footer, in the same run. This rule is that generator's drift guard — it fires
12	// when a page's stamp disagrees with `package.json`, which is what a hand-edit,
13	// a half-applied release, or a page added without the stamp all look like.
14	//
15	// SCOPE. Every tracked `site/**.html` that carries the footer copyright element
16	// (`class="copyright"`). A page without that element has no claim to check; a
17	// page with it must carry a stamp, and the stamp must match.
18	
19	const PAGE = /^site\/.*\.html$/;
20	const COPYRIGHT = /class="copyright"/;
21	
22	// The stamp as authored: `title="version 1.0821.34"` on the copyright element.
23	// Exported so the generator and the fixture spell it one way.
24	export const STAMP = /title="version ([^"]*)"/;
25	
26	const rule = {
27	  id: 'claudinite-website/site-version-tooltip',
28	  severity: 'blocking',
29	  description: "A site page's footer version tooltip must carry package.json's version",
30	  doc: '.claudinite/local/packs/claudinite-website/RULES.md',
31	  why: 'the tooltip is the only place a visitor can read which build they are on, and a stale copy names a build that was never served',
32	
33	  run(ctx) {
34	    const pkg = ctx.read('package.json');
35	    if (pkg === null) return [];
36	    let version;
37	    try { version = JSON.parse(pkg).version; } catch { return []; }
38	    if (!version) return [];
39	
40	    const out = [];
41	    const pages = [...new Set([...ctx.tracked, ...(ctx.files || [])])].filter((f) => PAGE.test(f));
42	
43	    for (const page of pages) {
44	      const text = ctx.read(page);
45	      if (text === null || !COPYRIGHT.test(text)) continue;
46	
47	      const lines = text.split('\n');
48	      const at = lines.findIndex((l) => COPYRIGHT.test(l));
49	      const stamped = STAMP.exec(lines[at] ?? '')?.[1];
50	
51	      if (stamped === version) continue;
52	      out.push(finding(rule, {
53	        file: page,
54	        line: at + 1,
55	        what: stamped === undefined
56	          ? 'the footer copyright carries no version tooltip'
57	          : `the footer names version ${stamped}, but package.json says ${version}`,
58	        fix: 'run `npm run bump-version` — it writes package.json and stamps every page from it; never hand-edit either side',
59	      }));
60	    }
61	
62	    return out;
63	  },
64	};
65	
66	export default rule;
