1	// Dependency-free by design: a local pack's checks must load without the
2	// vendored mount, so this returns plain finding objects rather than importing
3	// engine/checks/helpers/findings.mjs.
4	
5	const PKG = 'package.json';
6	const VERIFY = 'scripts/verify.sh';
7	
8	// The `node --test <globs...>` invocation, wherever it appears in a shell script
9	// or a package.json script string. Anchored per line so verify.sh's prose
10	// comments above it can mention the command without matching.
11	const NODE_TEST = /^\s*node --test\s+(.+?)\s*$/m;
12	
13	// If verify.sh delegates to the package script instead of repeating the globs,
14	// there is one source of truth and nothing to drift — the check stands down.
15	const DELEGATES = /\bnpm (?:run )?test\b/;
