65	// The ignore patterns that can cover `dir`: git reads a .gitignore per directory,
66	// so every ancestor of `dir` gets one — root first, deepest last, which is also
67	// git's precedence order (the last matching pattern wins). A .gitignore *inside*
68	// `dir` is excluded: it cannot cause its own directory to be ignored. Each entry
69	// is returned as { path, negated, anchored }, normalised to a repo-relative path
70	// or a bare name git matches at any depth below that .gitignore's directory.
71	function patterns(ctx, dir) {
72	  const segs = dir.split('/').slice(0, -1);
73	  const bases = ['', ...segs.map((_, i) => segs.slice(0, i + 1).join('/'))];
74	  const out = [];
75	  for (const base of new Set(bases)) {
76	    const text = ctx.read(joinPath(base, '.gitignore'));
77	    if (text === null) continue;
78	    for (const raw of text.split('\n')) {
79	      const line = raw.trim();
80	      if (!line || line.startsWith('#')) continue;
81	      const negated = line.startsWith('!');
82	      const body = (negated ? line.slice(1) : line).replace(/\/+$/, '');
83	      if (!body) continue;
84	      const anchored = body.includes('/');
85	      out.push({ base, negated, anchored, path: anchored ? joinPath(base, body.replace(/^\/+/, '')) : body });
86	    }
87	  }
88	  return out;
89	}
90	
91	const covers = (p, dir) => (p.anchored
92	  ? dir === p.path || dir.startsWith(`${p.path}/`)
93	  // A bare name matches any path component at or below the .gitignore's directory.
94	  : (dir === p.base || dir.startsWith(`${p.base}/`) || p.base === '')
95	    && dir.split('/').includes(p.path));
96	
97	// Last matching pattern wins in git, negation included.
98	function ignored(ctx, dir) {
99	  const hits = patterns(ctx, dir).filter((p) => covers(p, dir));
100	  return hits.length > 0 && !hits[hits.length - 1].negated;
101	}
102	
103	const rule = {
104	  id: 'render-outputs-gitignored',
105	  severity: 'blocking',
106	  description: 'Every directory a script renders into is gitignored',
107	  doc: '.claudinite/local/packs/vascular-coloring/skills/vessel-overlay-review/SKILL.md',
108	  why: 'overlay renders are regenerated from the scripts, not data — an output directory that is not ignored gets swept into the repo by the first `git add -A` after a run, and from then on a stale PNG is what reviewers see instead of what the current script draws',
