110	  run(ctx) {
111	    const out = [];
112	    for (const file of ctx.tracked) {
113	      if (!file.endsWith('.py') || file.startsWith(SHARED)) continue;
114	      const text = ctx.read(file);
115	      if (text === null) continue;
116	      for (const dir of createdDirs(file, text)) {
117	        if (ignored(ctx, dir.path)) continue;
118	        out.push({
119	          rule: rule.id,
120	          severity: rule.severity,
121	          file,
122	          line: dir.line,
123	          what: `${file} renders into ${dir.path}/, which no .gitignore entry covers`,
124	          why: rule.why,
125	          fix: `add \`/${dir.path}/\` to .gitignore (with a comment naming the command that regenerates it, as the existing render entries do); if ${dir.path}/ holds real data or agreed ground truth rather than renders, it belongs under references/ instead`,
126	          doc: rule.doc,
127	        });
128	      }
129	    }
130	    return out;
131	  },
132	};
133	
134	export default rule;
