import { finding } from '../../../engine/checks/helpers/findings.mjs';
import { classificationLine, classesIn } from '../../../engine/checks/helpers/session-transcript.mjs';

// The testable half of RULES.md's "Put the `Comment class:` line on its own
// line": the classifier reads the WHOLE classification line and adds EVERY
// class token it finds (`classesIn()` matches globally), so a natural-sounding
//     Comment class: other — not a correction, feature request, or process-change
// declares all four classes, not `other`. A stray `feature` then arms whatever
// feature-gated rule the consuming repo runs against the branch, even when it
// never touched a product feature.
//
// This asserts the MANDATED FORM, not the author's intent. RULES.md says to
// write the class alone and put any explanation on the next line, so the line
// either is that or it is not — a question every character of it answers. An
// intent-inferring draft (fire only on a class token following a negation word)
// is unbounded in the wrong direction: the harm comes from a class token being
// PRESENT, and prose smuggles them in without negating anything —
//     Comment class: other — unrelated to any feature request      (declares feature)
//     Comment class: other, setting the feature question aside     (declares feature)
//     Comment class: correction | feature | process-change | other (declares all four)
// — the last a verbatim paste of the menu, the likeliest way this recurs, and
// exactly the shape a negation-word list stays silent on. Checking the form
// catches all three and needs no word list, because a conforming line has
// nowhere to hide a token.
//
// A genuinely mixed comment stays legal and stays silent: it names each part it
// really is, positively, on that one line (`Comment class: correction,
// process-change`). Whether several comma-separated classes are "honest" is
// exactly the intent judgment this rule refuses to make — the form is
// respected, so the classifier does what the line asked.
//
// ADVISORY, deliberately, where the underlying defect can be blocking-grade
// downstream: the transcript is append-only, so by the time this is observable
// the declaration cannot be retracted. A blocking finding here could never
// converge — it would spend cycles on something no edit can fix. Its job is to
// name the cause the moment it appears so the session doesn't re-derive it from
// an unexplained downstream failure.

// One class token, spelled as the classifier's own alternation spells it, so
// this check models what `classesIn()` sees rather than a second opinion of it.
const CLASS = String.raw`(?:correction|feature|process[\s-]change|other)`;
// The mandated form: class tokens joined by a declaration separator, nothing
// else. `|` is deliberately NOT a separator — it is how the menu itself is
// rendered, so pasting it verbatim fails this pattern rather than reading as a
// multi-class declaration.
const CONFORMING_RE = new RegExp(String.raw`^\s*${CLASS}(?:\s*(?:,|&|\+|and)\s*${CLASS})*\s*\.?\s*$`, 'i');

const rule = {
  id: 'basics/comment-class-menu',
  severity: 'advisory',
  description: 'The `Comment class:` line must carry the class alone — every class token on it is declared, however the line phrases them',
  doc: 'packs/basics/RULES.md',
  scope: 'work',
  why: 'the classifier adds every class token on the classification line, so any explanation sharing that line declares the classes it mentions — including ones that arm a rule the session never meant to trigger',

  run(work) {
    // Only the latest owner turn is judged: the transcript is append-only, so
    // an earlier turn's line was already reported at its own Stop and can
    // never converge.
    const turn = work.conversation().ownerTurns().last();
    if (!turn.exists) return [];
