function classFindings(replyText) {
  const entries = [
    { type: 'user', timestamp: '2026-01-01T00:00:00Z', message: { role: 'user', content: 'please look at the release job' } },
    { type: 'assistant', timestamp: '2026-01-01T00:00:01Z', message: { role: 'assistant', content: [{ type: 'text', text: replyText }] } },
  ];
  const root = makeRepo({});
  const { path, cleanup: rmTranscript } = makeTranscript(entries);
  try {
    return runRule(commentClassMenu, buildContext({ root, mode: 'changed', transcriptPath: path }));
  } finally { cleanup(root); rmTranscript(); }
}

test('comment-class-menu: fires on a stray class smuggled in without negating anything', () => {
  const found = classFindings('Comment class: other — unrelated to any feature request\n\nProceeding.');
  assert.equal(found.length, 1);
  assert.equal(found[0].rule, 'basics/comment-class-menu');
  assert.equal(found[0].severity, 'advisory');
  assert.match(found[0].what, /feature/);
});

test('comment-class-menu: fires on the menu pasted verbatim out of the prompt', () => {
  const found = classFindings('Comment class: correction | feature | process-change | other');
  assert.equal(found.length, 1);
  // `|` is the menu's own separator, never a declaration separator.
  assert.match(found[0].what, /correction/);
  assert.match(found[0].what, /feature/);
});

test('comment-class-menu: fires on an explanation sharing the line even when it smuggles no class', () => {
  const found = classFindings('Comment class: correction — fixed the typo');
  assert.equal(found.length, 1);
  assert.match(found[0].what, /correction/);
});

test('comment-class-menu: silent on the class declared alone', () => {
  assert.deepEqual(classFindings('Comment class: other\n\nNot a correction, feature request, or process-change — just a note.'), []);
});

test('comment-class-menu: silent on an honest multi-class declaration', () => {
  assert.deepEqual(classFindings('Comment class: correction, process-change\n\nFixing it and updating the procedure.'), []);
});

test('comment-class-menu: silent when there is no classification line at all', () => {
  assert.deepEqual(classFindings('Sure, doing that now.'), []);
});

test('comment-class-menu: silent when the line names no known class at all', () => {
  assert.deepEqual(classFindings('Comment class: misc'), []);
});

