    // Only the latest owner turn is judged: the transcript is append-only, so
    // an earlier turn's line was already reported at its own Stop and can
    // never converge.
    const turn = work.conversation().ownerTurns().last();
    if (!turn.exists) return [];
    const line = classificationLine(turn.reply());
    // No classification line at all is a different rule's finding.
    if (!line) return [];

    // Everything after the `Comment class:` colon — the prefix cannot contain
    // one (the helper's pattern forbids it), so the first colon is the split.
    const declaration = line.slice(line.indexOf(':') + 1);
    if (CONFORMING_RE.test(declaration)) return [];

    const declared = [...classesIn(declaration)].sort();
    // A line naming no known class at all is unclassified — a different rule's finding.
    if (!declared.length) return [];

    return [finding(rule, {
      file: '(conversation)',
      what: `the \`Comment class:\` line carries more than the class it means, so the classifier reads it as declaring ${declared.map((c) => `\`${c}\``).join(', ')}`,
      fix: 'write the class alone on its own line — `Comment class: other` — and put any explanation on the NEXT line; a genuinely mixed comment names each part it really is, comma-separated, on that one line. The transcript is append-only, so re-declaring cleanly on a later line does not override this one',
    })];
  },
};

export default rule;

