});

test('lib: hasSpread is true only when the init literal spreads something', () => {
  assert.equal(hasSpread('{ ...init }'), true);
  assert.equal(hasSpread('{ bubbles: true }'), false);
  assert.equal(hasSpread(null), false);
});

